import type { OpenCodeManagementProfile } from '../../management/profile.js';
import type { RegisteredProcessRootSource } from '../../process/registeredProcessContracts.js';
import type { OpenCodeV2OwnedSessionSelection, OpenCodeV2TransportConfig } from '@agent-teams/provider-implementations/opencode';

const unavailable = (): never => {
  throw new ManagementCommandError('held');
};
const prompt = 'Reply only OK. Do not use tools, access files or run commands.';

/**
 * One finite native mechanism under the existing ModelProbeOwner journal.
 * Preparation allocates nothing; only its durably admitted run may create a child.
 */
export function createOpenCodeV2ModelProbe(
  raw: OpenCodeManagementProfile,
  input: ModelProbeInput,
  isCurrent: () => boolean,
  options: { processCustody?: RegisteredProcessRootSource; coordination?: true;
    readiness?: { observeProvider?(provider: unknown, fileProof?: AcceptedOpenCodeV2FileKey): void; expectedProvider?: Record<string, unknown> } } = {}
): NativeModelProbe & { wasRejected(): boolean; coordinationObservation(): NativeCoordinationObservation | undefined } {
  const profile = selectOpenCodeV2ManagementModel(openCodeManagementProfileSchema.parse(raw), input);
  if (
    profile.nativeGeneration !== 'v2' ||
    profile.protocolRevision !== '2.1.4' ||
    !profile.embedded ||
    !profile.nativeModel ||
    input.limits ||
    input.modelContext !== undefined ||
    hasUntrustedOpenCodeBinaryOverride(profile.environment)
  )
    throw new ManagementCommandError('invalid');
  const { embedded } = profile;
  const captured = managementDigest({ profile, commandId: input.commandId,
    ...(options.readiness ? { readinessPhase: options.coordination ? 'coordination' : 'ordinary' } : {}) });
  const purposeBound = options.coordination || options.readiness !== undefined;
  const timeoutMs = purposeBound ? Math.min(profile.modelProbeTimeoutMs ?? 90000, 90000)
    : profile.modelProbeTimeoutMs ?? 90000;
  const directories = new Map<string, { dev: bigint; ino: bigint }>();
  try {
    for (const directory of [
      profile.cwd,
      ...['HOME', 'XDG_CONFIG_HOME', 'XDG_DATA_HOME', 'XDG_CACHE_HOME'].map(
        (key) => profile.environment[key]
      ),
    ]) {
      if (!directory || realpathSync(directory) !== directory) return unavailable();
      const stat = lstatSync(directory, { bigint: true });
      if (!stat.isDirectory() || stat.isSymbolicLink()) return unavailable();
      directories.set(directory, { dev: stat.dev, ino: stat.ino });
    }
  } catch {
    return unavailable();
  }
  const namespaceRoots = new Map<string, { dev: bigint; ino: bigint }>();
  const abort = new AbortController();
  let closed = false;
  let released = false;
  let starting: Promise<void> | undefined;
  let running: Promise<boolean> | undefined;
  let closing: Promise<boolean> | undefined;
  let activeSignal: AbortSignal | undefined;
  let ownerCleanupUnknown = false;
  let rejected = false;
  let runState: 'not-started' | 'pending' | 'true' | 'false' | 'threw' = 'not-started';
  let outcome: 'unobserved' | 'succeeded' | 'failed' | 'cancelled' | 'unknown' = 'unobserved';
  let errorClass: 'none' | 'held' | 'invalid' | 'conflict' | 'busy' | 'unknown' = 'none';
  type CloseStage = 'request-drain' | 'owner-client' | 'driver-close' | 'server-stop' | 'namespace' | 'close-result';
  let firstCloseFailure: { stage: CloseStage; reason: 'unconfirmed' | 'threw' | 'identity' } | undefined;
  const noteCloseFailure = (stage: CloseStage, reason: NonNullable<typeof firstCloseFailure>['reason']) => {
    if (!coordination) firstCloseFailure ??= { stage, reason };
  };
  let coordinationResult: NativeCoordinationObservation | undefined;
  const requests = new Set<Promise<void>>();
  let driver: Session | undefined;
  let server: ReturnType<typeof createOpenCodeV2EmbeddedServer> | undefined;
  let ready: Awaited<ReturnType<NonNullable<typeof server>['start']>> | undefined;
  let deadline = 0;
  const nativeSessionId = 'ses_' + captured.slice(0, 40);
  const contextCurrent = () => {
    if (
      closed ||
      abort.signal.aborted ||
      activeSignal?.aborted ||
      hasUntrustedOpenCodeBinaryOverride(process.env)
    )
      return false;
    try {
      if (!isCurrent()) return false;
      for (const [directory, identity] of directories) {
        const stat = lstatSync(directory, { bigint: true });
        if (
          !stat.isDirectory() ||
          stat.isSymbolicLink() ||
          realpathSync(directory) !== directory ||
          stat.dev !== identity.dev ||
          stat.ino !== identity.ino
        )
          return false;
      }
      return true;
    } catch {
      return false;
    }
  };
  const coordination = options.coordination ? new OpenCodeCoordinationEndpoint() : undefined;
  const coordinationSource = coordination && !options.readiness
    ? captureCoordinationConfiguration(profile, input, contextCurrent) : undefined;
  const configuration = captureOpenCodeV2Configuration(profile, profile.nativeModel, contextCurrent);
  const noTool = openCodeV2NoToolConfig(profile, configuration.configuration);
  const configured = configuration.configuration;
  const observedProvider: Record<string, unknown> = configured ? {
    npm: typeof configured.package === 'string' ? configured.package.replace(/^aisdk:/, '') : undefined,
    options: configured.settings ?? {}, models: configured.models ?? {},
  } : {};
  if (options.readiness?.expectedProvider && managementDigest(observedProvider) !==
      managementDigest(options.readiness.expectedProvider)) return unavailable();
  let config: Record<string, unknown> = noTool.config;
  let selection: OpenCodeV2OwnedSessionSelection = noTool.selection;
  const credential = captureOpenCodeV2SessionCredential(profile, input.providerId,
    configuration.isCurrent, configuration.key, configuration.selectedFile);
  const current = coordinationSource
    ? () => credential.isCurrent() && coordinationSource.isCurrent() : credential.isCurrent;
  let nativeCredential: OpenCodeV2OwnedSessionSelection['credential'];
  const assertCurrent = (signal?: AbortSignal) => {
    signal?.throwIfAborted();
    if (!current() || Date.now() >= deadline) unavailable();
  };
  async function beforeRequest(signal: AbortSignal): Promise<() => void> {
    assertCurrent(signal);
    // Reserve before the asynchronous native measurement. Shutdown fences new
    // admissions and drains these leases before aborting the Session transport.
    const settled = Promise.withResolvers<void>();
    requests.add(settled.promise);
    const release = () => {
      if (requests.delete(settled.promise)) settled.resolve();
    };
    try {
      const custody = await server?.readNativeCustody(AbortSignal.any([signal, abort.signal]));
      assertCurrent(signal);
      if (
        !custody ||
        !ready ||
        custody.pid !== ready.pid ||
        custody.startIdentity !== ready.startIdentity ||
        custody.version !== '2.1.4'
      )
        unavailable();
      return release;
    } catch (error) {
      release();
      throw error;
    }
  }
  const readPassword = () => {
    assertCurrent();
    if (!server) return unavailable();
    return server.readPassword();
  };
  async function withClient<T>(
    signal: AbortSignal,
    action: (client: ReturnType<typeof createOpenCodeV2OwnedSessionClient>, config: OpenCodeV2TransportConfig) => Promise<T>
  ): Promise<T> {
    assertCurrent(signal);
    if (!ready) return unavailable();
    const config: OpenCodeV2TransportConfig = {
      endpoint: ready.endpoint,
      directory: profile.cwd,
      nativeSessionId,
      version: '2.1.4',
      beforeRequest,
      readPassword,
      signal: AbortSignal.any([signal, abort.signal]),
      deadline,
    };
    const client = createOpenCodeV2OwnedSessionClient(config);
    let failed = false;
    let originalFailure: unknown;
    let result!: T;
    try {
      result = await action(client, config);
      assertCurrent(signal);
    } catch (error) {
      failed = true;
      originalFailure = error;
    }
    try {
      await client.dispose();
    } catch (error) {
      ownerCleanupUnknown = true;
      noteCloseFailure('owner-client', 'threw');
      if (!failed) {
        failed = true;
        originalFailure = error;
      }
    }
    if (failed) throw originalFailure;
    return result;
  }
  async function namespace(root: string): Promise<string> {
    const directory = await mkdtemp(
      join(root, 'agent-teams-v2-probe-' + captured.slice(0, 16) + '-')
    );
    const stat = lstatSync(directory, { bigint: true });
    namespaceRoots.set(directory, { dev: stat.dev, ino: stat.ino });
    return directory;
  }
  async function start(signal: AbortSignal): Promise<void> {
    assertCurrent(signal);
    if (coordination) {
      coordinationSource?.beforeAllocation();
      await coordination.start(deadline, signal, current);
      assertCurrent(signal);
      ({ config, selection } = openCodeV2CoordinationConfig(profile, coordination, configuration.configuration));
    }
    const data = await namespace(profile.environment.XDG_DATA_HOME!);
    assertCurrent(signal);
    const configDirectory = await namespace(profile.environment.XDG_CONFIG_HOME!);
    assertCurrent(signal);
    server = createOpenCodeV2EmbeddedServer({
      profile,
      embedded,
      databasePath: join(data, 'probe.sqlite'),
      configDirectory,
      startupTimeoutMs: Math.min(profile.timeoutMs, purposeBound ? deadline - Date.now() : timeoutMs),
      canAllocate: current,
      ...(options.processCustody ? { processCustody: options.processCustody } : {}),
      ...(configuration.selectedFile ? { selectedFile: { source: configuration.selectedFile, mode: 'fresh' as const } } : {}),
      config,
    });
    coordinationSource?.beforeAllocation();
    ready = await server.start(signal);
    assertCurrent(signal);
    await withClient(signal, async (client, wire) => {
      const identity = await client.identity();
      if (identity.pid !== ready!.pid || identity.version !== '2.1.4') return unavailable();
      nativeCredential = await credential.prepare(wire, client, undefined,
        integrationId => server!.selectedFileKey(ready!, integrationId));
      await attestOpenCodeV2ModelSelection(client, selection.model,
        { signal, deadline, isCurrent: current });
      options.readiness?.observeProvider?.({
        ...observedProvider,
        ...(nativeCredential ? { credentialScopeDigest: nativeCredential.scopeDigest } : {}),
      }, credential.fileProof());
      assertCurrent(signal);
      await client.createSession({ ...selection, ...(nativeCredential ? { credential: nativeCredential } : {}) });
    });
    coordination?.bindSession(nativeSessionId);
    const binding = {
      tenantId: 'provider-management',
      projectId: profile.profileId,
      sessionId: input.commandId,
      generation: 1,
    };
    const factory = createOpenCodeV2DriverFactory({
      capabilities: coordination ? ['text', 'tools'] : ['text'],
      readCheckpoint: async () => unavailable(),
      resolveConfiguration: async (request) => {
        assertCurrent(signal);
        if (request.checkpointRef !== undefined || !ready) return undefined;
        return {
          binding,
          configRevision: profile.configRevision,
          endpoint: ready.endpoint,
          directory: profile.cwd,
          version: '2.1.4',
          nativeSessionId,
          trustedBinding: captured,
          accountBinding: profile.accountBinding,
          readPassword,
          beforeRequest,
          // Pending native custody retains its original drain; only admitted HTTP
          // also observes this probe's original cancellation.
          fetchImpl: (request, init) => fetch(request, { ...init,
            signal: AbortSignal.any([signal, abort.signal, ...(init?.signal ? [init.signal] : [])]) }),
          limits: {
            queuedInputs: 1,
            inputBytes: 1024,
            outputBytes: 32768,
            outputEvents: 128,
            pendingInteractions: 1,
            timeoutMs: purposeBound ? Math.max(1, deadline - Date.now()) : timeoutMs,
          },
          probe: async (probeSignal) =>
            withClient(probeSignal, async (client) => {
              const observed = await client.readSession();
              return (
                managementDigest({
                  agent: observed.agent,
                  model: observed.model,
                  permissions: observed.permissions,
                  ...(observed.credential ? { credential: observed.credential } : {}),
                }) === managementDigest({ ...selection, ...(nativeCredential ? { credential: nativeCredential } : {}) }) &&
                (await client.savedPermissionsEmpty()) &&
                (await client.builtinPluginsOnly()) &&
                await (async () => {
                  const mcp = await client.readMcp();
                  return coordination ? mcp.length === 1 && mcp[0]?.name === coordinationServer &&
                    mcp[0].status === 'connected' && coordination.catalogCurrent() : mcp.length === 0;
                })()
              );
            }),
          confirmStopped: () => server!.stopOwned(),
        };
      },
    });
    const opened = await factory.open({
      ...binding,
      configRevision: profile.configRevision,
      requiredCapabilities: coordination ? ['text', 'tools'] : ['text'],
    });
    driver = opened.driver;
    assertCurrent(signal);
  }
  async function run(signal: AbortSignal, originalDeadline?: number): Promise<boolean> {
    if (purposeBound && (originalDeadline === undefined || !Number.isSafeInteger(originalDeadline) ||
        originalDeadline <= Date.now() || originalDeadline - Date.now() > timeoutMs)) unavailable();
    deadline = purposeBound ? originalDeadline! : Date.now() + timeoutMs;
    const combined = AbortSignal.any([signal, abort.signal,
      AbortSignal.timeout(purposeBound ? Math.max(1, deadline - Date.now()) : timeoutMs)]);
    activeSignal = combined;
    starting = start(combined);
    await starting;
    assertCurrent(combined);
    if (!driver) return unavailable();
    if (coordination) {
      if (options.readiness) {
        coordinationResult = await readNativeCoordination(driver, nativeSessionId, coordination,
          captured, combined, deadline, current);
        return coordinationResult?.status === 'compatible';
      }
      return runNativeCoordination(driver, nativeSessionId, coordination, captured, combined, deadline, current);
    }
    const inputId = 'model-probe-' + captured.slice(0, 32);
    const operationRef = 'model-probe-operation-' + captured.slice(0, 32);
    const handed = await driver.submit({ inputId, operationRef, content: prompt });
    if (!handed.ok) return false;
    let hasText = false;
    for await (const event of driver.observe()) {
      assertCurrent(combined);
      if (
        event.sessionRef !== driver.sessionRef ||
        event.inputId !== inputId ||
        event.operationRef !== operationRef
      )
        return false;
      if (event.kind === 'text') hasText ||= event.text.trim().length > 0;
      else if (event.kind === 'result') {
        // V2 emits failed only for the original qualified execution.failed + idle
        // cut. Transport/cancellation/output failures are not a rejection proof.
        const consumed = event.outcome;
        outcome = consumed === 'succeeded' || consumed === 'failed' || consumed === 'cancelled' ? consumed : 'unknown';
        rejected = consumed === 'failed' && event.code === undefined;
        return event.outcome === 'succeeded' && hasText;
      }
      else if (event.kind !== 'usage') return false;
    }
    return false;
  }
  return {
    timeoutMs,
    wasRejected: () => rejected,
    coordinationObservation: () => coordinationResult === undefined ? undefined : { ...coordinationResult },
    nativeFileKeyWitness: () => {
      if (!released) return undefined;
      const proof = credential.fileProof();
      if (configuration.selectedFile && !proof) return unavailable();
      return proof;
    },
    run: (signal, originalDeadline) => {
      if (running) return running;
      if (coordination) return (running = run(signal, originalDeadline));
      runState = 'pending';
      return (running = run(signal, originalDeadline).then(result => {
        runState = result ? 'true' : 'false'; return result;
      }, (error: unknown) => {
        runState = 'threw'; errorClass = 'unknown';
        try {
          if (error && (typeof error === 'object' || typeof error === 'function')) {
            const field = Object.getOwnPropertyDescriptor(error, 'code');
            const code: unknown = field && 'value' in field ? field.value : undefined;
            if (code === 'held' || code === 'invalid' || code === 'conflict' || code === 'busy') errorClass = code;
          }
        } catch { /* An opaque diagnostic cannot replace the original exception. */ }
        throw error;
      }));
    },
    close: originalDeadline => {
      closed = true;
      coordination?.seal();
      abort.abort();
      if (closing) return closing;
      const work = (async () => {
        await starting?.catch(() => {});
        // Rejected late custody checks cannot send credentials. Give their
        // original finite requests time to settle before SPI abort; a missing
        // release remains UNKNOWN and is never converted to a clean cancel.
        let timer: ReturnType<typeof setTimeout> | undefined;
        let clean = false;
        try {
          clean = await Promise.race([
            Promise.all([...requests]).then(() => true),
            new Promise<false>((resolve) => {
              timer = setTimeout(() => resolve(false), Math.min(timeoutMs, 5000,
                purposeBound ? Math.max(0, (originalDeadline ?? deadline) - Date.now()) : 5000));
            }),
          ]);
        } finally {
          clearTimeout(timer);
        }
        if (!clean) noteCloseFailure('request-drain', 'unconfirmed');
        clean = clean && !ownerCleanupUnknown;
        try {
          if (driver) {
            const confirmed = (await driver.close()).cleanup === 'confirmed';
            if (!confirmed) noteCloseFailure('driver-close', 'unconfirmed');
            clean = confirmed && clean;
          }
        } catch {
          noteCloseFailure('driver-close', 'threw');
          clean = false;
        }
        try {
          if (server) {
            const stopped = await server.stopOwned();
            if (!stopped) noteCloseFailure('server-stop', 'unconfirmed');
            clean = stopped && clean;
          }
        } catch {
          noteCloseFailure('server-stop', 'threw');
          clean = false;
        }
        if (coordination) {
          try { clean = await coordination.close() && clean; } catch { clean = false; }
        }
        if (!clean) return false;
        try {
          for (const [directory, identity] of namespaceRoots) {
            const stat = lstatSync(directory, { bigint: true });
            if (
              !stat.isDirectory() ||
              stat.isSymbolicLink() ||
              realpathSync(directory) !== directory ||
              stat.dev !== identity.dev ||
              stat.ino !== identity.ino
            ) {
              noteCloseFailure('namespace', 'identity');
              return false;
            }
            await rm(directory, { recursive: true, force: true });
          }
          return true;
        } catch {
          noteCloseFailure('namespace', 'threw');
          return false;
        }
      })();
      closing = (purposeBound ? closeCoordinationByDeadline(work, originalDeadline ?? deadline) : work)
        .then(clean => {
          released = clean;
          if (!clean && !coordination) {
            noteCloseFailure('close-result', 'unconfirmed');
            try {
              const diagnostic = channel('agent-teams:opencode-v2:host-probe-close-failed');
              if (diagnostic.hasSubscribers) diagnostic.publish({ probeDigest: captured, runState, outcome,
                errorClass, ...firstCloseFailure });
            } catch { /* Failure-only observation cannot change the original cleanup result. */ }
          }
          return clean;
        });
      return closing;
    },
  };
}

/** TEST-only passive diagnostics for the original source Host on the qualified Node/platform tuples. */
import { channel } from 'node:diagnostics_channel';
import { lstat, open, unlink } from 'node:fs/promises';
import { performance } from 'node:perf_hooks';
import { fileURLToPath } from 'node:url';
import type { ChildProcess } from 'node:child_process';

const prefix = 'TEST_OPENCODE_V2_DIAGNOSTIC ';
const maximum = 256;
const maximumTraceBytes = 64 * 1024, maximumLineBytes = 512, reservedLineBytes = maximumLineBytes + 1;
const events = ['child-spawn', 'child-ready', 'child-failed', 'child-exit', 'child-output-limit',
  'child-input-ended', 'host-input-ended', 'request', 'request-send-headers', 'request-body-sent',
  'response', 'response-end', 'request-error', 'read-cut-failed', 'metadata-read-failed', 'host-probe-close-failed', 'trace-limit'] as const;
const routes = ['info', 'session-create', 'session-read', 'instructions', 'permissions', 'plugins',
  'mcp', 'log', 'prompt', 'provider-catalog', 'model-catalog', 'model-default', 'integration-read',
  'integration-connect', 'credential-remove', 'other-api'] as const;
const stages = ['input', 'executable', 'profile', 'graph', 'configuration', 'effect', 'runtime', 'scope', 'server', 'address', 'unknown'] as const;
const codes = ['ABORT_ERR', 'ECONNRESET', 'ECONNREFUSED', 'EPIPE', 'ETIMEDOUT',
  'UND_ERR_ABORTED', 'UND_ERR_SOCKET', 'UND_ERR_HEADERS_TIMEOUT', 'UND_ERR_BODY_TIMEOUT', 'unknown'] as const;
const signals = ['SIGTERM', 'SIGKILL', 'SIGINT', 'SIGABRT', 'SIGSEGV', 'SIGBUS', 'unknown'] as const;
const contentEncodings = ['none', 'gzip', 'deflate', 'br', 'other'] as const;
const record = (value: unknown): Record<string, unknown> =>
  value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
const choice = <T extends string>(value: unknown, allowed: readonly T[]): T | null =>
  typeof value === 'string' && allowed.includes(value as T) ? value as T : null;
const integer = (value: unknown, max = 3_600_000): number | null =>
  typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value <= max ? value : null;

const readCutStages = ['before-session', 'before-log', 'messages', 'after-log', 'after-session', 'comparison'] as const;
const readCutReasons = ['deadline', 'cleanup_unknown', 'native_read_cleanup_unknown', 'invalid_native_read_response',
  'invalid_native_read_json', 'native_session_binding_mismatch', 'invalid_native_envelope', 'invalid_native_page',
  'invalid_native_model', 'invalid_native_position', 'invalid_native_identity', 'incomplete_native_log',
  'incomplete_native_transcript', 'native_cut_byte_budget', 'frame_limit', 'body_limit', 'transport_failure',
  'authority_mismatch', 'disposed', 'media_type', 'http_failure', 'unknown'] as const;

/** The private D channel carries only fixed data; never execute a diagnostic getter. */
function projectReadCutFailure(value: unknown) {
  try {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
    const own = (key: string): unknown => {
      const field = Object.getOwnPropertyDescriptor(value, key);
      return field && 'value' in field ? field.value : undefined;
    };
    const stage = choice(own('stage'), readCutStages), reason = choice(own('reason'), readCutReasons);
    const elapsedMs = integer(own('elapsedMs'), 60_000), deadlineExpired = own('deadlineExpired'), aborted = own('aborted');
    if (!stage || !reason || elapsedMs === null || typeof deadlineExpired !== 'boolean' || typeof aborted !== 'boolean')
      return undefined;
    return { stage, reason, elapsedMs, deadlineExpired, aborted };
  } catch { return undefined; }
}

const metadataReadStages = ['admission', 'native-client', 'identity', 'plugins', 'permissions', 'mcp',
  'credential', 'directory', 'activation-wait', 'current', 'projection', 'dispose', 'result-current'] as const;
const metadataReadReasons = ['held', 'conflict', 'invalid', 'busy', 'deadline', 'cleanup_unknown',
  'transport_failure', 'authority_mismatch', 'disposed', 'http_failure', 'media_type', 'body_limit',
  'frame_limit', 'invalid_response', 'invalid_native_catalog', 'native_catalog_binding_mismatch',
  'capabilities_pending', 'unqualified_version', 'ABORT_ERR', 'unknown'] as const;

/** Original metadata read failure only; null abort observation is limited to pre-signal admission. */
function projectMetadataReadFailure(value: unknown) {
  try {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
    const own = (key: string): unknown => {
      const field = Object.getOwnPropertyDescriptor(value, key);
      return field && 'value' in field ? field.value as unknown : undefined;
    };
    const stage = choice(own('stage'), metadataReadStages), reason = choice(own('reason'), metadataReadReasons);
    const elapsedMs = integer(own('elapsedMs')), deadlineExpired = own('deadlineExpired'), aborted = own('aborted');
    if (!stage || !reason || elapsedMs === null || typeof deadlineExpired !== 'boolean' ||
        !(typeof aborted === 'boolean' || aborted === null && stage === 'admission')) return undefined;
    return { stage, reason, elapsedMs, deadlineExpired, aborted };
  } catch { return undefined; }
}

/** Host observation only: no raw D error, authority read or inferred final outcome. */
function projectHostProbeCloseFailure(value: unknown) {
  try {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
    const own = (key: string): unknown => {
      const field = Object.getOwnPropertyDescriptor(value, key);
      return field && 'value' in field ? field.value as unknown : undefined;
    };
    const probeDigest = own('probeDigest'), runState = choice(own('runState'), ['not-started', 'pending', 'true', 'false', 'threw']);
    const outcome = choice(own('outcome'), ['unobserved', 'succeeded', 'failed', 'cancelled', 'unknown']);
    const errorClass = choice(own('errorClass'), ['none', 'held', 'invalid', 'conflict', 'busy', 'unknown']);
    const stage = choice(own('stage'), ['request-drain', 'owner-client', 'driver-close', 'server-stop', 'namespace', 'close-result']);
    const reason = choice(own('reason'), ['unconfirmed', 'threw', 'identity']);
    if (typeof probeDigest !== 'string' || !/^[a-f0-9]{64}$/.test(probeDigest) ||
        !runState || !outcome || !errorClass || !stage || !reason) return undefined;
    return { probeDigest, runState, outcome, errorClass, stage, reason };
  } catch { return undefined; }
}

/** Project again at the receipt boundary; native text/IDs/credentials are never retained. */
export function createPassiveNativeDiagnosticCapture() {
  const entries: Record<string, unknown>[] = [];
  let pending = '', ordinary = 0, bytes = 0, readObserved = false, metadataObserved = false, closeObserved = false, limitObserved = false, limited = false;
  // These counters belong to this one original capture, including all of its Host epochs.
  return {
    entries,
    get limited() { return limited; },
    accept(chunk: Buffer, epoch: number) {
      if (chunk.length + Buffer.byteLength(pending) > maximumTraceBytes) { pending = ''; limited = true; return; }
      pending += chunk.toString('utf8');
      for (let end = pending.indexOf('\n'); end >= 0; end = pending.indexOf('\n')) {
        const line = pending.slice(0, end); pending = pending.slice(end + 1);
        if (!line.startsWith(prefix) || Buffer.byteLength(line) > maximumLineBytes) continue;
        try {
          const value = record(JSON.parse(line.slice(prefix.length)) as unknown);
          const event = choice(value.event, events), atMs = integer(value.atMs);
          if (!event || atMs === null) continue;
          const failedCut = event === 'read-cut-failed' ? projectReadCutFailure(value) : undefined;
          const failedMetadata = event === 'metadata-read-failed' ? projectMetadataReadFailure(value) : undefined;
          const failedClose = event === 'host-probe-close-failed' ? projectHostProbeCloseFailure(value) : undefined;
          if (event === 'read-cut-failed' && !failedCut || event === 'metadata-read-failed' && !failedMetadata ||
              event === 'host-probe-close-failed' && !failedClose) continue;
          const failure = failedMetadata ?? failedCut;
          const entry = { epoch, event, atMs, child: integer(value.child, 5), request: integer(value.request, 4096),
            route: choice(value.route, routes), method: choice(value.method, ['GET', 'POST', 'PUT', 'DELETE']),
            durationMs: failure?.elapsedMs ?? integer(value.durationMs), status: integer(value.status, 599),
            contentEncoding: choice(value.contentEncoding, contentEncodings),
            stage: failedClose?.stage ?? failure?.stage ?? choice(value.stage, stages),
            code: failedClose?.reason ?? failure?.reason ?? choice(value.code, codes),
            exitCode: integer(value.exitCode, 255), signal: choice(value.signal, signals),
            ...(failure ? { deadlineExpired: failure.deadlineExpired, aborted: failure.aborted } : {}),
            ...(failedClose ? { probeDigest: failedClose.probeDigest, runState: failedClose.runState,
              outcome: failedClose.outcome, errorClass: failedClose.errorClass } : {}) };
          const size = Buffer.byteLength(JSON.stringify(entry)) + 1;
          if (size > reservedLineBytes) continue;
          const reserve = (readObserved ? 0 : reservedLineBytes) + (metadataObserved ? 0 : reservedLineBytes) +
            (closeObserved ? 0 : reservedLineBytes) + (limitObserved ? 0 : reservedLineBytes);
          if (failedClose) {
            if (closeObserved || bytes + size > maximumTraceBytes - reserve + reservedLineBytes) continue;
            closeObserved = true;
          } else if (failedMetadata) {
            if (metadataObserved || bytes + size > maximumTraceBytes - reserve + reservedLineBytes) continue;
            metadataObserved = true;
          } else if (failedCut) {
            if (readObserved || bytes + size > maximumTraceBytes - reserve + reservedLineBytes) continue;
            readObserved = true;
          } else if (event === 'trace-limit') {
            if (limitObserved || bytes + size > maximumTraceBytes - reserve + reservedLineBytes) continue;
            limitObserved = true; limited = true;
          } else {
            // Reserve all three failure observations within the original 257-row ceiling.
            if (ordinary >= maximum - 3 || bytes + size > maximumTraceBytes - reserve) { limited = true; continue; }
            ordinary++;
          }
          bytes += size;
          entries.push(entry);
        } catch { /* Other Host diagnostics are deliberately not retained. */ }
      }
    },
  };
}

const cpuCategories = ['configuration-read', 'credential-read', 'team-writer-authority',
  'custody-image', 'provider-transport', 'other', 'idle'] as const;
type CpuCategory = typeof cpuCategories[number];
const cpuWriterFamilies = ['namespace-fence', 'team-state', 'team-state-validation',
  'launch-binding-read', 'launch-binding-current', 'launch-binding-clone', 'other-writer'] as const;
const cpuWriterCallers = ['node-timer', 'v2-request-admission', 'v2-request-password', 'v2-read-snapshot',
  'runtime-session-read', 'provider-attestation-wait', 'unclassified'] as const;
const cpuNamespaceFamilies = ['directoryPath', 'tree', 'controller-lock', 'residual'] as const;
const cpuControllerLockFunctions = ['codeOf', 'statOrMissing', 'readOrMissing', 'unlinkOrMissing',
  'removeEmptyGate', 'isProcessAlive', 'parsePid', 'writeComplete', 'recoverGate', 'acquireGate',
  'readLockInfo', 'sameLock', 'recoverDataLock', 'releaseLock', 'tryAcquire', 'sleepSync',
  'resolveLockOptions', 'acquireFileLockSync'];
type CpuUnavailable = 'not-started' | 'host-not-exited' | 'missing' | 'stat-failed' | 'file-shape' |
  'empty-profile' | 'profile-over-limit' | 'open-failed' | 'read-failed' | 'incomplete-read' |
  'changed-file' | 'invalid-profile' | 'discard-failed';
const maximumCpuBytes = 16 * 1024 * 1024;
type CpuFileSize = {
  /** Exact within the read limit; a capped lower bound when fileOverLimit is true. */
  fileBytes?: number;
  fileOverLimit?: boolean;
};
type CpuTotals = { category: CpuCategory; exclusiveSamples: number; exclusiveSampledUs: number;
  inclusiveSamples: number; inclusiveSampledUs: number };
type CpuWriterTotals = { family: typeof cpuWriterFamilies[number]; exclusiveSamples: number;
  exclusiveSampledUs: number };
type CpuWriterCallerTotals = { caller: typeof cpuWriterCallers[number]; exclusiveSamples: number;
  exclusiveSampledUs: number; namespaceSamples: number; namespaceSampledUs: number };
type CpuNamespaceTotals = { family: typeof cpuNamespaceFamilies[number]; exclusiveSamples: number;
  exclusiveSampledUs: number };
export type OriginalHostCpuProfile = CpuFileSize & ({ status: 'unavailable'; reason: CpuUnavailable; rawDiscarded: boolean } | {
  status: 'available'; rawDiscarded: boolean; samplingIntervalUs: 1000 | 10000; profileDurationUs: number;
  sampledUs: number; unsampledUs: number; nodeCount: number; sampleCount: number;
  attribution: 'nearest-allowlisted-stack-frame'; categories: CpuTotals[];
  /** Partition of the unchanged exclusive team-writer-authority totals, not additional sampled time. */
  teamWriterDetails: CpuWriterTotals[];
  /** Sampled caller ancestry, not invocation counts, request latency or a specific timer owner. */
  teamWriterCallers: { attribution: 'outermost-allowlisted-caller-on-sampled-stack'; rows: CpuWriterCallerTotals[] };
  /** Partition of namespace-fence only; descendant attribution, not isolated function self-time. */
  namespaceFenceDetails: CpuNamespaceTotals[];
});

/** Closed source families only. No frame name, source URL, path or stack leaves this projection. */
function cpuCategory(frame: Record<string, unknown>): number | undefined {
  if (typeof frame.url !== 'string' || frame.url.length > 16_384 ||
      typeof frame.functionName !== 'string' || frame.functionName.length > 16_384)
    throw new Error('Invalid TEST CPU frame');
  const path = frame.url.replaceAll('\\', '/');
  if (/\/(?:adapters\/providers\/(?:OpenCodeConfigurationSource|OpenCodeV2CapturedConfiguration)|composition\/openCodeSelectedProviderConfiguration)\.[jt]s$/.test(path)) return 0;
  if (/\/adapters\/providers\/OpenCodeV2(?:CredentialScope|SessionCredential|CredentialOperation)\.[jt]s$/.test(path)) return 1;
  if (/\/(?:composition\/(?:captureMemberProviderAuthority|teamRoster)|adapters\/profile\/ProfileWriterLease)\.[jt]s$/.test(path) ||
      /\/composition\/RuntimeTeamCoordinator\.[jt]s$/.test(path) && frame.functionName === 'assertCurrent') return 2;
  if (/\/(?:adapters\/providers\/(?:OpenCodeV2EmbeddedGraph|OpenCodeV2CustodyReadback|WindowsJobCustody)|process\/(?:readPackagedProcessArtifact|DarwinRegisteredProcess)|composition\/processCustody)\.[jt]s$/.test(path) ||
      /\/adapters\/providers\/OpenCodeV2EmbeddedMemberProvider\.[jt]s$/.test(path) && frame.functionName === 'attest') return 3;
  if (/\/features\/provider-session-implementation\/adapters\/opencode-protocol\/[^/]+\.js$/.test(path)) return 4;
  if (frame.functionName === '(idle)') return 6;
  return undefined;
}

/** Exact source/function families within the original writer category; no additional raw fields escape. */
function cpuWriterFamily(frame: Record<string, unknown>): number | undefined {
  if (typeof frame.url !== 'string' || typeof frame.functionName !== 'string') return undefined;
  const path = frame.url.replaceAll('\\', '/'), name = frame.functionName;
  if (/\/adapters\/team\/TeamOwnerStore\.[jt]s$/.test(path) &&
      (name === 'fenced' || name === 'validateNamespace')) return 0;
  // state also includes the existing roster recovery; its residual is not pure validation CPU.
  if (/\/team\/TeamOwner\.[jt]s$/.test(path) && name === 'state') return 1;
  if (/\/team\/(?:TeamRuntimeRegistration|TeamRosterTransitions)\.[jt]s$/.test(path) && name === 'validate') return 2;
  if (/\/adapters\/team\/FileTeamRuntimeBindings\.[jt]s$/.test(path)) {
    if (name === 'read') return 3;
    if (name === 'current') return 4;
  }
  // This candidate is accepted only below the exact binding-current context during tree traversal.
  if (path === 'node:internal/worker/js_transferable' && name === 'structuredClone') return 5;
  return undefined;
}

/** Closed caller contexts only; missing async ancestry remains explicitly unclassified. */
function cpuWriterCaller(frame: Record<string, unknown>): number | undefined {
  if (typeof frame.url !== 'string' || typeof frame.functionName !== 'string') return undefined;
  const path = frame.url.replaceAll('\\', '/'), name = frame.functionName;
  if (path === 'node:internal/timers' && (name === 'processTimers' || name === 'listOnTimeout')) return 0;
  if (/\/adapters\/providers\/OpenCodeV2RequestAdmission\.[jt]s$/.test(path) && name === 'beforeRequest' ||
      /\/features\/provider-session-implementation\/adapters\/opencode-protocol\/v2-request-admission\.js$/.test(path) && name === 'acquire') return 1;
  if (/\/adapters\/providers\/OpenCodeV2(?:Embedded)?MemberProvider\.[jt]s$/.test(path) && name === 'readPassword' ||
      /\/features\/provider-session-implementation\/adapters\/opencode-protocol\/v2-execution-transport\.js$/.test(path) && name === 'requestHeaders') return 2;
  if (/\/adapters\/providers\/OpenCodeV2ReadOnlySnapshot\.[jt]s$/.test(path) &&
      ['read', 'attest', 'checkLease', 'beforeRequest', 'readPassword', 'fetchImpl'].includes(name)) return 3;
  if (/\/runtime\/RuntimeOwner\.[jt]s$/.test(path) && name === 'readSession') return 4;
  if (/\/adapters\/providers\/OpenCodeV2MemberProvider\.[jt]s$/.test(path) && name === 'waitForAttestation') return 5;
  return undefined;
}

/** Named controller paths only: staged numeric package identities remain residual. */
function cpuNamespaceFamily(frame: Record<string, unknown>): number | undefined {
  if (typeof frame.url !== 'string' || typeof frame.functionName !== 'string') return undefined;
  const path = frame.url.replaceAll('\\', '/'), name = frame.functionName;
  if (/\/adapters\/team\/TeamOwnerStore\.[jt]s$/.test(path)) {
    if (name === 'directoryPath') return 0;
    if (name === 'tree') return 1;
  }
  if (/\/agent-teams-controller\/(?:src|dist)\/internal\/fileLock\.js$/.test(path)) {
    // A protected callback is not lock work merely because this wrapper is its ancestor.
    if (name === 'withFileLockSync' || name === 'withFileLock') return 3;
    if (cpuControllerLockFunctions.includes(name)) return 2;
  }
  return undefined;
}

function projectCpuProfile(raw: unknown, samplingIntervalUs: 1000 | 10000): OriginalHostCpuProfile {
  const invalid = (): never => { throw new Error('Invalid TEST CPU profile'); };
  const value = record(raw), start = integer(value.startTime, Number.MAX_SAFE_INTEGER),
    end = integer(value.endTime, Number.MAX_SAFE_INTEGER);
  if (start === null || end === null || end <= start || end - start > 3_600_000_000 ||
      !Array.isArray(value.nodes) || value.nodes.length < 1 || value.nodes.length > 100_000 ||
      !Array.isArray(value.samples) || !Array.isArray(value.timeDeltas) ||
      value.samples.length < 1 || value.samples.length > 1_000_000 ||
      value.samples.length !== value.timeDeltas.length) return invalid();
  const duration = end - start;
  const nodes = new Map<number, { category: number | undefined; writerFamily: number | undefined;
    namespaceFamily: number | undefined; writerCaller: number | undefined; children: number[] }>();
  for (const rawNode of value.nodes) {
    const node = record(rawNode), id = integer(node.id, 1_000_000);
    if (id === null || id < 1 || nodes.has(id) ||
        node.children !== undefined && !Array.isArray(node.children)) return invalid();
    const children: number[] = [];
    for (const child of (node.children ?? []) as unknown[]) {
      const selected = integer(child, 1_000_000);
      if (selected === null || selected < 1) return invalid();
      children.push(selected);
    }
    const callFrame = record(node.callFrame);
    nodes.set(id, { category: cpuCategory(callFrame), writerFamily: cpuWriterFamily(callFrame),
      namespaceFamily: cpuNamespaceFamily(callFrame), writerCaller: cpuWriterCaller(callFrame), children });
  }
  const first = integer(record(value.nodes[0]).id, 1_000_000)!;
  type StackAttribution = { exclusive: number; inclusive: number; writerFamily: number;
    namespaceFamily: number; writerCaller: number | undefined };
  const frames = new Map<number, StackAttribution>();
  const pending: (StackAttribution & { id: number })[] = [
    { id: first, exclusive: 5, inclusive: 0, writerFamily: 6, namespaceFamily: 3, writerCaller: undefined },
  ];
  while (pending.length) {
    const current = pending.pop()!, node = nodes.get(current.id);
    if (!node || frames.has(current.id)) return invalid(); // One connected, acyclic original stack tree.
    const exclusive = node.category ?? current.exclusive;
    const inclusive = current.inclusive | (node.category === undefined ? 0 : 1 << node.category);
    const writerFamily = node.writerFamily === 5
      ? (current.writerFamily === 4 ? 5 : current.writerFamily)
      : node.writerFamily ?? current.writerFamily;
    const namespaceFamily = exclusive === 2 && writerFamily === 0
      ? node.writerFamily === 0 ? 3 : node.namespaceFamily ??
        (current.exclusive === 2 && current.writerFamily === 0 ? current.namespaceFamily : 3)
      : 3;
    const writerCaller = current.writerCaller ?? node.writerCaller;
    frames.set(current.id, { exclusive, inclusive, writerFamily, namespaceFamily, writerCaller });
    for (const id of node.children) pending.push({ id, exclusive, inclusive, writerFamily, namespaceFamily, writerCaller });
  }
  if (frames.size !== nodes.size) return invalid();
  const categories: CpuTotals[] = cpuCategories.map(category => ({ category,
    exclusiveSamples: 0, exclusiveSampledUs: 0, inclusiveSamples: 0, inclusiveSampledUs: 0 }));
  const teamWriterDetails: CpuWriterTotals[] = cpuWriterFamilies.map(family => ({ family,
    exclusiveSamples: 0, exclusiveSampledUs: 0 }));
  const callerRows: CpuWriterCallerTotals[] = cpuWriterCallers.map(caller => ({ caller,
    exclusiveSamples: 0, exclusiveSampledUs: 0, namespaceSamples: 0, namespaceSampledUs: 0 }));
  const namespaceFenceDetails: CpuNamespaceTotals[] = cpuNamespaceFamilies.map(family => ({ family,
    exclusiveSamples: 0, exclusiveSampledUs: 0 }));
  let sampledUs = 0;
  for (let index = 0; index < value.samples.length; index++) {
    const id = integer(value.samples[index], 1_000_000), delta = integer(value.timeDeltas[index], duration);
    const frame = id === null ? undefined : frames.get(id);
    if (!frame || delta === null || sampledUs + delta > duration) return invalid();
    sampledUs += delta;
    const exclusive = categories[frame.exclusive]!;
    exclusive.exclusiveSamples++; exclusive.exclusiveSampledUs += delta;
    if (frame.exclusive === 2) {
      const detail = teamWriterDetails[frame.writerFamily]!;
      detail.exclusiveSamples++; detail.exclusiveSampledUs += delta;
      const caller = callerRows[frame.writerCaller ?? 6]!;
      caller.exclusiveSamples++; caller.exclusiveSampledUs += delta;
      if (frame.writerFamily === 0) { caller.namespaceSamples++; caller.namespaceSampledUs += delta; }
      if (frame.writerFamily === 0) {
        const namespace = namespaceFenceDetails[frame.namespaceFamily]!;
        namespace.exclusiveSamples++; namespace.exclusiveSampledUs += delta;
      }
    }
    // A category is counted at most once per stack. Inclusive columns overlap; never sum them.
    const inclusive = frame.inclusive | 1 << frame.exclusive;
    for (let category = 0; category < categories.length; category++) if (inclusive & 1 << category) {
      categories[category]!.inclusiveSamples++; categories[category]!.inclusiveSampledUs += delta;
    }
  }
  return { status: 'available', rawDiscarded: false, samplingIntervalUs,
    profileDurationUs: duration, sampledUs, unsampledUs: duration - sampledUs,
    nodeCount: nodes.size, sampleCount: value.samples.length,
    attribution: 'nearest-allowlisted-stack-frame', categories, teamWriterDetails, namespaceFenceDetails,
    teamWriterCallers: { attribution: 'outermost-allowlisted-caller-on-sampled-stack', rows: callerRows } };
}

/** Read after the original process exits. This measures sampled Host stacks, not Bun CPU or request latency. */
export async function readOriginalHostCpuProfile(
  path: string | undefined, originalExited: boolean, samplingIntervalUs: 1000 | 10000 = 1000
): Promise<OriginalHostCpuProfile> {
  if (!path) return { status: 'unavailable', reason: 'not-started', rawDiscarded: true };
  if (!originalExited) return { status: 'unavailable', reason: 'host-not-exited', rawDiscarded: false };
  let result: OriginalHostCpuProfile = { status: 'unavailable', reason: 'stat-failed', rawDiscarded: false };
  let reason: CpuUnavailable = 'stat-failed';
  const fileSize: CpuFileSize = {};
  try {
    const before = await lstat(path);
    reason = 'file-shape';
    if (!Number.isSafeInteger(before.size) || before.size < 0) throw new Error('Invalid TEST CPU size');
    fileSize.fileBytes = Math.min(before.size, maximumCpuBytes + 1);
    fileSize.fileOverLimit = before.size > maximumCpuBytes;
    if (!before.isFile() || before.isSymbolicLink() || before.nlink !== 1) throw new Error('Invalid TEST CPU file');
    reason = 'empty-profile';
    if (before.size === 0) throw new Error('Empty TEST CPU file');
    reason = 'profile-over-limit';
    if (fileSize.fileOverLimit) throw new Error('Oversized TEST CPU file');
    const same = (after: typeof before) => after.isFile() && after.nlink === 1 &&
      after.dev === before.dev && after.ino === before.ino && after.size === before.size &&
      after.mtimeMs === before.mtimeMs && after.ctimeMs === before.ctimeMs;
    reason = 'open-failed';
    const handle = await open(path, 'r');
    let bytes: Buffer;
    let closeFailure: { error: unknown } | undefined;
    try {
      reason = 'changed-file';
      if (!same(await handle.stat())) throw new Error('Changed TEST CPU file');
      reason = 'read-failed';
      bytes = Buffer.alloc(before.size);
      let offset = 0;
      while (offset < bytes.length) {
        reason = 'read-failed';
        const read = await handle.read(bytes, offset, bytes.length - offset, offset);
        reason = 'incomplete-read';
        if (!read.bytesRead) throw new Error('Incomplete TEST CPU file');
        offset += read.bytesRead;
      }
      reason = 'changed-file';
      if (!same(await handle.stat()) || !same(await lstat(path))) throw new Error('Changed TEST CPU file');
    } finally { await handle.close().catch((error: unknown) => { closeFailure = { error }; }); }
    if (closeFailure) { reason = 'read-failed'; throw closeFailure.error; }
    reason = 'invalid-profile';
    result = projectCpuProfile(JSON.parse(bytes.toString('utf8')) as unknown, samplingIntervalUs);
  } catch (error) {
    result = { status: 'unavailable', reason: reason === 'stat-failed' && record(error).code === 'ENOENT'
      ? 'missing' : reason, rawDiscarded: false };
  }
  try { await unlink(path); result.rawDiscarded = true; }
  catch (error) {
    if (record(error).code === 'ENOENT') result.rawDiscarded = true;
    else result = { status: 'unavailable', reason: 'discard-failed', rawDiscarded: false };
  }
  return { ...result, ...fileSize };
}

/** Classify the pinned Undici Buffer-pair shape; no raw header value is retained. */
function responseContentEncoding(headers: unknown): typeof contentEncodings[number] {
  if (!Array.isArray(headers) || headers.length > 256 || headers.length % 2 !== 0) return 'other';
  let selected: typeof contentEncodings[number] = 'none';
  for (let index = 0; index < headers.length; index += 2) {
    const name = headers[index], value = headers[index + 1];
    if (!Buffer.isBuffer(name)) return 'other';
    if (name.length !== 16 || name.toString('ascii').toLowerCase() !== 'content-encoding') continue;
    if (selected !== 'none' || !Buffer.isBuffer(value) || value.length > 32) return 'other';
    selected = choice(value.toString('ascii').trim().toLowerCase(), ['gzip', 'deflate', 'br']) ?? 'other';
  }
  return selected;
}

function observeOriginalHost(): void {
  const started = performance.now();
  let ordinary = 0, emittedBytes = 0, children = 0, requests = 0, readObserved = false, metadataObserved = false, closeObserved = false, limited = false;
  const elapsed = () => Math.max(0, Math.round(performance.now() - started));
  const line = (value: Record<string, unknown>) => prefix + JSON.stringify({ atMs: elapsed(), ...value }) + '\n';
  const write = (value: string) => { emittedBytes += Buffer.byteLength(value); process.stderr.write(value); };
  const emit = (value: Record<string, unknown>) => {
    const frame = line(value), size = Buffer.byteLength(frame);
    if (size > reservedLineBytes) return;
    const reserve = (readObserved ? 0 : reservedLineBytes) + (metadataObserved ? 0 : reservedLineBytes) +
      (closeObserved ? 0 : reservedLineBytes) + (limited ? 0 : reservedLineBytes);
    if (value.event === 'host-probe-close-failed') {
      if (closeObserved || emittedBytes + size > maximumTraceBytes - reserve + reservedLineBytes) return;
      closeObserved = true; write(frame); return;
    }
    if (value.event === 'metadata-read-failed') {
      if (metadataObserved || emittedBytes + size > maximumTraceBytes - reserve + reservedLineBytes) return;
      metadataObserved = true; write(frame); return;
    }
    if (value.event === 'read-cut-failed') {
      if (readObserved || emittedBytes + size > maximumTraceBytes - reserve + reservedLineBytes) return;
      readObserved = true; write(frame); return;
    }
    if (limited) return;
    if (ordinary >= maximum - 3 || emittedBytes + size > maximumTraceBytes - reserve) {
      limited = true; write(line({ event: 'trace-limit' })); return;
    }
    ordinary++; write(frame);
  };
  process.stdin.once('end', () => emit({ event: 'host-input-ended' }));
  channel('agent-teams:opencode-v2:read-cut-failed').subscribe(message => {
    try {
      const failure = projectReadCutFailure(message);
      if (failure) emit({ event: 'read-cut-failed', ...failure });
    } catch { /* A passive TEST subscriber cannot replace native failure/cleanup. */ }
  });
  channel('agent-teams:opencode-v2:metadata-read-failed').subscribe(message => {
    try {
      const failure = projectMetadataReadFailure(message);
      if (failure) emit({ event: 'metadata-read-failed', ...failure });
    } catch { /* A passive TEST subscriber cannot replace original metadata failure/cleanup. */ }
  });
  channel('agent-teams:opencode-v2:host-probe-close-failed').subscribe(message => {
    try {
      const failure = projectHostProbeCloseFailure(message);
      if (failure) emit({ event: 'host-probe-close-failed', ...failure });
    } catch { /* A passive TEST observation cannot change the original close result. */ }
  });
  const childEntry = fileURLToPath(new URL('../../../dist/adapters/providers/OpenCodeV2EmbeddedChild.js', import.meta.url));
  channel('child_process').subscribe(message => {
    const child = record(message).process as ChildProcess | undefined;
    child?.once('spawn', () => {
      if (child.spawnargs.at(-1) !== childEntry || children >= 5) return;
      const selected = ++children;
      emit({ event: 'child-spawn', child: selected });
      child.stdin?.once('finish', () => emit({ event: 'child-input-ended', child: selected }));
      let output = '', bytes = 0;
      const observe = (chunk: Buffer) => {
        bytes += chunk.length;
        if (bytes > 64 * 1024) { child.stdout?.off('data', observe); emit({ event: 'child-output-limit', child: selected }); return; }
        output += chunk.toString('utf8');
        for (let end = output.indexOf('\n'); end >= 0; end = output.indexOf('\n')) {
          const line = output.slice(0, end); output = output.slice(end + 1);
          try {
            const value = record(JSON.parse(line) as unknown);
            if (value.type === 'ready' && value.pid === child.pid && value.version === '2.1.4')
              emit({ event: 'child-ready', child: selected });
            else if (value.type === 'failed') emit({ event: 'child-failed', child: selected, stage: choice(value.stage, stages) ?? 'unknown' });
          } catch { /* No raw engine output is retained. */ }
        }
      };
      child.stdout?.on('data', observe);
      child.once('exit', (exitCode, signal) => emit({ event: 'child-exit', child: selected,
        exitCode, signal: signal === null ? null : choice(signal, signals) ?? 'unknown' }));
      child.once('close', () => { child.stdout?.off('data', observe); output = ''; });
    });
  });
  const pending = new WeakMap<object, { request: number; route: string; method: string; started: number;
    sendHeadersObserved: boolean; bodySentObserved: boolean }>();
  channel('undici:request:create').subscribe(message => {
    const request = record(record(message).request);
    if (requests >= 4096 || typeof request.origin !== 'string' || !/^http:\/\/127\.0\.0\.1:[1-9]\d{0,4}$/.test(request.origin) ||
        typeof request.path !== 'string' || !request.path.startsWith('/api/')) return;
    const path = request.path.split('?')[0]!;
    const route = path === '/api/info' ? 'info' : path === '/api/session' ? 'session-create'
      : path === '/api/permission/saved' ? 'permissions' : path === '/api/plugin' ? 'plugins'
      : path === '/api/mcp' ? 'mcp' : /\/instructions?(?:\/|$)/.test(path) ? 'instructions'
      : path === '/api/provider' ? 'provider-catalog' : path === '/api/model' ? 'model-catalog'
      : path === '/api/model/default' ? 'model-default'
      : /^\/api\/integration\/[^/]+\/connect\/key$/.test(path) ? 'integration-connect'
      : /^\/api\/integration\/[^/]+$/.test(path) ? 'integration-read'
      : /^\/api\/credential\/[^/]+$/.test(path) ? 'credential-remove'
      : /\/log$/.test(path) ? 'log' : /\/prompt$/.test(path) ? 'prompt'
      : /^\/api\/session\/[^/]+$/.test(path) ? 'session-read' : 'other-api';
    const method = choice(request.method, ['GET', 'POST', 'PUT', 'DELETE']);
    if (!method) return;
    const value = { request: ++requests, route, method, started: performance.now(),
      sendHeadersObserved: false, bodySentObserved: false };
    pending.set(request, value); emit({ event: 'request', request: value.request, route, method });
  });
  // Exact Node24.21 writer phases only; neither proves server ingress or native acceptance.
  // Restrict extra events to the two metadata seams, retaining the original total trace budget.
  for (const [name, event, marker] of [
    ['undici:client:sendHeaders', 'request-send-headers', 'sendHeadersObserved'],
    ['undici:request:bodySent', 'request-body-sent', 'bodySentObserved'],
  ] as const) channel(name).subscribe(message => {
    const value = pending.get(record(record(message).request));
    if (!value || value.route !== 'plugins' && value.route !== 'model-catalog' || value[marker]) return;
    value[marker] = true;
    emit({ event, request: value.request, route: value.route, method: value.method,
      durationMs: Math.max(0, Math.round(performance.now() - value.started)) });
  });
  // Headers alone do not show when a finite native log body finishes arriving.
  // Observe only log trailers: no native bytes, header values or new requests.
  channel('undici:request:trailers').subscribe(message => {
    const value = pending.get(record(record(message).request));
    if (value?.route !== 'log') return;
    emit({ event: 'response-end', request: value.request, route: value.route, method: value.method,
      durationMs: Math.max(0, Math.round(performance.now() - value.started)) });
  });
  for (const [name, event] of [['undici:request:headers', 'response'], ['undici:request:error', 'request-error']] as const)
    channel(name).subscribe(message => {
      const row = record(message), value = pending.get(record(row.request));
      if (!value) return;
      emit({ event, request: value.request, route: value.route, method: value.method,
        durationMs: Math.max(0, Math.round(performance.now() - value.started)),
        ...(event === 'response' ? { status: integer(record(row.response).statusCode, 599),
          contentEncoding: responseContentEncoding(record(row.response).headers) }
          : { code: choice(record(row.error).code, codes) ?? 'unknown' }) });
    });
}

// Importing the receipt projection in the parent does not activate an observer.
if ((process.platform === 'linux' && process.arch === 'x64' ||
      (process.platform === 'darwin' || process.platform === 'win32') &&
      (process.arch === 'arm64' || process.arch === 'x64')) && process.version === 'v24.21.0' &&
    process.execArgv.some((argument, index, args) => argument === '--import' &&
      (args[index + 1] === import.meta.url || args[index + 1] === fileURLToPath(import.meta.url))))
  observeOriginalHost();

import { OpenCodeInputWindowCapture } from './input-window-capture.ts'
import { createHash, randomUUID } from 'node:crypto'
import { setTimeout as delay } from 'node:timers/promises'
import type { CloseReceipt, Event, EventPayload, FailureCode, Input, InteractionReply, Reply, Session } from '@agent-teams/provider-session-contracts'
import { bounded, deferred, EventFeed } from '../provider-session-io/io.ts'
import type { DriverPermission, DriverProtocol, DriverSessionConfig, DriverTurn } from './driver-protocol.ts'
import { executionWasNotSubmitted } from './v2-failures.ts'
import { AttachmentFailure, inputFingerprint, prepareAttachments, snapshotInput, validCanonicalInput, validateAttachments } from '../provider-session-io/attachments.ts'

const failure = (code: FailureCode, unsent = false) => ({ ok: false as const, code, ...(unsent ? { delivery: 'known-not-sent' as const } : {}) })
const handoff = (input: Input) => ({ ok: true as const, value: { inputId: input.inputId, operationRef: input.operationRef,
  delivery: 'client-consumed' as const, providerAcceptance: 'unknown' as const } })
type Pending = { capture?: OpenCodeInputWindowCapture; input: Input; nativeId: string; done: ReturnType<typeof deferred<ReturnType<typeof handoff> | ReturnType<typeof failure>>>; handed: boolean; preparing: boolean; interactionsRevoked: boolean; interactionAbort: AbortController; turn?: DriverTurn }
type Interaction = { permission: DriverPermission; owner: Pending; answering: boolean }

/** Volatile bounded native-session consumer. Runtime owns durable operations and recovery. */
export class OpenCodeDriverSession implements Session {
  readonly sessionRef: string
  private readonly config: DriverSessionConfig
  private readonly abort = new AbortController()
  private readonly protocol: DriverProtocol
  private readonly feed: EventFeed<Event>
  private readonly queued: Pending[] = []
  private readonly interactions = new Map<string, Interaction>()
  private readonly settledInteractions = new Set<string>()
  private active: Pending | undefined
  private state: 'open' | 'unavailable' | 'closed' = 'open'
  private wakeup = deferred<void>()
  private readonly loop: Promise<void>
  private closing: Promise<CloseReceipt> | undefined
  private control: Promise<Reply<{ requested: true; terminal: 'unconfirmed' }>> | undefined
  private readonly replies = new Set<Promise<Reply<void>>>()
  private turnEvents = 0
  private turnBytes = 0
  private knownTerminal: Extract<Event, { kind: 'result' }> | undefined
  constructor(config: DriverSessionConfig, createProtocol: (signal: AbortSignal) => DriverProtocol) {
    this.config = config; this.sessionRef = config.binding.sessionId
    this.protocol = createProtocol(this.abort.signal)
    this.feed = new EventFeed(config.limits.outputEvents, config.limits.outputBytes)
    this.loop = this.run()
  }
  submit(supplied: Input) {
    if (!this.isOpen()) {return Promise.resolve(failure('unavailable', true))}
    let input: Input
    try { input = snapshotInput(supplied); validateAttachments(input, this.config.engine, this.config.attachmentModel, this.config.attachments) }
    catch (error) { return Promise.resolve(failure(error instanceof AttachmentFailure ? error.code : 'invalid-config', true)) }
    if (!validCanonicalInput(input, Math.min(this.config.limits.inputBytes, 256 * 1024))) {return Promise.resolve(failure('backpressure', true))}
    if (this.active?.input.inputId === input.inputId || this.active?.input.operationRef === input.operationRef
      || this.queued.some(item => item.input.inputId === input.inputId || item.input.operationRef === input.operationRef)) {return Promise.resolve(failure('stale', true))}
    if (this.queued.length >= this.config.limits.queuedInputs) {return Promise.resolve(failure('backpressure', true))}
    const nativeId = 'msg_' + createHash('sha256').update(JSON.stringify([this.config.trustedBinding,
      this.config.nativeSessionId, this.sessionRef, input.inputId, input.operationRef, ...((input.attachments?.length ?? 0) > 0 ? [inputFingerprint(input)] : [])])).digest('hex')
    const pending: Pending = { input, nativeId, done: deferred(), handed: false, preparing: (input.attachments?.length ?? 0) > 0, interactionsRevoked: false, interactionAbort: new AbortController() }
    this.queued.push(pending); this.wake(); return pending.done.promise
  }
  observe(): AsyncIterable<Event> { return this.feed }
  async checkReadiness(): Promise<Reply<void>> {
    if (!this.isOpen()) {return failure('unavailable')}
    const controller = new AbortController()
    const signal = AbortSignal.any([controller.signal, this.abort.signal])
    try {
      const ready = await bounded(this.config.probe(signal), this.config.limits.timeoutMs)
      if (!ready || signal.aborted || !this.isOpen()) {return failure('dependency-unavailable')}
      return { ok: true, value: undefined }
    } catch { return failure('dependency-unavailable') } finally { controller.abort() }
  }
  respondToInteraction(ref: string, reply: InteractionReply): Promise<Reply<void>> {
    const interaction = this.interactions.get(ref)
    if (!this.isOpen() || !interaction || interaction.owner !== this.active || interaction.owner.interactionsRevoked || interaction.answering || this.control) {return Promise.resolve(failure('stale'))}
    if (reply.kind !== 'permission' || !['allow', 'deny'].includes(reply.decision)) {return Promise.resolve(failure('unsupported'))}
    interaction.answering = true
    const work = this.answer(interaction, ref, reply.decision)
    this.replies.add(work)
    void work.finally(() => { this.replies.delete(work); this.wake() }).catch(() => {})
    return work
  }
  private async answer(interaction: Interaction, ref: string, decision: 'allow' | 'deny'): Promise<Reply<void>> {
    try {
      await this.protocol.replyPermission(interaction.permission.requestId, decision, interaction.owner.interactionAbort.signal)
      this.interactions.delete(ref); this.settledInteractions.add(ref)
      if (!this.isOpen() || this.active !== interaction.owner || interaction.owner.interactionsRevoked) {return failure('stale')}
      return { ok: true, value: undefined }
    } catch (error) {
      if (interaction.owner.interactionsRevoked && executionWasNotSubmitted(error)) {return failure('stale')}
      this.seal('unknown'); return failure('unknown')
    }
  }
  interrupt(operationRef: string): Promise<Reply<{ requested: true; terminal: 'unconfirmed' }>> {
    if (!this.isOpen() || !this.active || this.active.input.operationRef !== operationRef) {return Promise.resolve(failure('stale'))}
    if (this.active.preparing) {return Promise.resolve(failure('stale'))}
    if (this.control) {return this.control}
    const pending = this.active
    pending.interactionsRevoked = true; pending.interactionAbort.abort(); this.interactions.clear()
    const done = deferred<Reply<{ requested: true; terminal: 'unconfirmed' }>>(); this.control = done.promise
    void (async () => {
      try {
        if (!pending.turn) {throw new Error('unknown_native_handoff')}
        await pending.turn.interrupt()
        done.resolve({ ok: true, value: { requested: true, terminal: 'unconfirmed' } })
      } catch { this.seal('unknown'); done.resolve(failure('unknown')) }
      finally { this.control = undefined; this.wake() }
    })()
    return done.promise
  }
  checkpoint(): Reply<unknown> {
    if (!this.isOpen() || this.active || this.queued.length || this.control || this.replies.size || this.interactions.size) {return failure('unavailable')}
    return { ok: true, value: { version: 1, engine: this.config.engine, nativeSessionId: this.config.nativeSessionId,
      compatibility: this.config.compatibility } }
  }
  close(): Promise<CloseReceipt> {
    if (this.closing) {return this.closing}
    this.seal('unknown'); this.state = 'closed'; this.abort.abort(); this.wake()
    this.closing = (async () => {
      try {
        await bounded(Promise.all([this.loop, this.control, ...this.replies]), this.config.limits.timeoutMs)
        await bounded(this.protocol.dispose(), this.config.limits.timeoutMs)
        const stopped = await bounded(this.config.confirmStopped(), this.config.limits.timeoutMs)
        return { logicallyClosed: true as const, cleanup: stopped ? 'confirmed' as const : 'unknown' as const }
      } catch { return { logicallyClosed: true as const, cleanup: 'unknown' as const } }
      finally { this.feed.end() }
    })()
    return this.closing
  }
  private async run(): Promise<void> {
    try {
      while (this.state !== 'closed') {
        if (!this.isOpen() || this.active || this.control || this.replies.size || this.queued.length === 0) { await this.wakeup.promise; continue }
        const ready = await this.checkReadiness()
        if (!ready.ok) { this.seal(ready.code); continue }
        if (!this.isOpen() || this.hasControl()) {continue}
        const pending = this.queued.shift(); if (!pending) {continue}
        this.active = pending; this.turnEvents = 0; this.turnBytes = 0; this.settledInteractions.clear()
        try {
          const attachments = await prepareAttachments(pending.input, { trustedBinding: this.config.trustedBinding, sessionRef: this.sessionRef, port: this.config.attachments, signal: pending.interactionAbort.signal, timeoutMs: this.config.limits.timeoutMs })
          if (!this.canSubmit(pending)) { pending.done.resolve(failure('stale', true)); continue }
          if (!await this.observeBefore(pending)) { pending.done.resolve(failure('stale', true)); continue }
          pending.preparing = false
          const turn = await this.protocol.queue(pending.nativeId, pending.input.content, attachments)
          if (!this.isOpen()) { pending.done.resolve(failure('unknown')); continue }
          pending.turn = turn; pending.nativeId = turn.nativeInputId; pending.handed = true; pending.done.resolve(handoff(pending.input))
          await this.poll(pending, turn)
        } catch (error) {
          if (this.rejectAttachments(error, pending)) { continue }
          pending.capture?.gap('transport')
          if (!pending.handed && executionWasNotSubmitted(error)) {
            pending.done.resolve(failure('dependency-unavailable', true)); this.active = undefined; this.seal('dependency-unavailable')
          } else { pending.done.resolve(failure('unknown')); this.seal('unknown') }
        }
      }
    } finally { this.feed.end() }
  }
  private async observeBefore(pending: Pending): Promise<boolean> {
    if (this.config.capture) {
      pending.preparing = true
      pending.capture = new OpenCodeInputWindowCapture({ identity: { sessionRef: this.sessionRef, windowRef: randomUUID(),
        inputId: pending.input.inputId, operationRef: pending.input.operationRef, nativeSessionId: this.config.nativeSessionId,
        ...(this.config.engine === 'opencode-v2' ? { dialect: 'v2' as const } : {}) },
        port: this.config.capture, abort: this.abort.signal, timeoutMs: this.config.limits.timeoutMs,
        maxItems: this.config.limits.outputEvents, maxBytes: this.config.limits.outputBytes })
      await pending.capture.before()
    }
    return this.canSubmit(pending)
  }
  private canSubmit(pending: Pending): boolean { return this.isOpen() && this.active === pending && !pending.interactionsRevoked && !this.hasControl() }
  private rejectAttachments(error: unknown, pending: Pending): boolean {
    if (!(error instanceof AttachmentFailure) || pending.handed) { return false }
    pending.done.resolve(failure(error.code, true)); pending.interactionAbort.abort()
    if (this.active === pending) { this.active = undefined } this.wake(); return true
  }
  private async poll(pending: Pending, turn: DriverTurn): Promise<void> {
    const deadline = Date.now() + this.config.limits.timeoutMs
    while (this.isOpen() && this.active === pending) {
      if (Date.now() >= deadline) { this.seal('unknown'); return }
      const snapshot = await turn.read()
      if (!this.isOpen() || this.active !== pending) {return}
      const terminalCode = snapshot.terminal === 'failed' && snapshot.terminalCode === 'unsupported' ? 'unsupported' as const : undefined
      this.knownTerminal = snapshot.terminal ? { kind: 'result', outcome: snapshot.terminal, sessionRef: this.sessionRef,
        inputId: pending.input.inputId, operationRef: pending.input.operationRef, ...(terminalCode ? { code: terminalCode } : {}) } : undefined
      for (const fact of snapshot.facts) {this.emit(fact, pending)}
      if (!this.isOpen()) {return}
      if (snapshot.terminal) {
        pending.interactionsRevoked = true; pending.interactionAbort.abort()
        await pending.capture?.after(turn.nativeInputId, snapshot.terminal, snapshot.observations ?? [])
        if (!this.isOpen() || this.active !== pending) {return}
        this.emit({ kind: 'result', outcome: snapshot.terminal, ...(terminalCode ? { code: terminalCode } : {}) }, pending)
        this.knownTerminal = undefined; this.interactions.clear(); if (this.active === pending) {this.active = undefined}
        return
      }
      if (!this.control && !pending.interactionsRevoked) {this.admitPermissions(snapshot.permissions, pending)}
      await delay(this.protocol.pollIntervalMs, undefined, { signal: this.abort.signal })
    }
  }
  private admitPermissions(permissions: readonly DriverPermission[], owner: Pending): void {
    if (!this.isOpen() || this.active !== owner || owner.interactionsRevoked || this.control) {return}
    for (const permission of permissions) {
      const ref = owner.nativeId + ':' + permission.requestId
      if (this.interactions.has(ref) || this.settledInteractions.has(ref)) {continue}
      if (this.interactions.size >= this.config.limits.pendingInteractions) { this.seal('output-limit'); return }
      this.interactions.set(ref, { permission, owner, answering: false })
      this.emit({ kind: 'interaction', interactionRef: ref, request: { kind: 'permission', tool: permission.tool, input: permission.input } }, owner)
    }
  }
  private emit(fact: EventPayload, owner: Pending): void {
    this.turnEvents++; this.turnBytes += Buffer.byteLength(JSON.stringify(fact))
    const event: Event = structuredClone({ ...fact, sessionRef: this.sessionRef, inputId: owner.input.inputId, operationRef: owner.input.operationRef })
    if (this.turnEvents > this.config.limits.outputEvents || this.turnBytes > this.config.limits.outputBytes || !this.feed.push(event)) {
      this.seal('output-limit', event.kind === 'result' ? { ...event, code: 'output-limit' } : undefined)
    }
  }
  private seal(code: FailureCode, knownTerminal?: Extract<Event, { kind: 'result' }>): void {
    if (!this.isOpen()) {return}
    this.state = 'unavailable'
    const pending = this.active; this.active = undefined
    if (pending) {
      pending.interactionsRevoked = true; pending.interactionAbort.abort()
      pending.capture?.gap(code === 'output-limit' ? 'limit' : 'transport')
      pending.done.resolve(failure(code, pending.preparing))
      this.feed.finishWith(pending.preparing ? { kind: 'diagnostic', code, sessionRef: this.sessionRef } : knownTerminal ?? (code === 'output-limit' && this.knownTerminal ? { ...this.knownTerminal, code } : undefined) ?? { kind: 'result', outcome: 'unknown', code, sessionRef: this.sessionRef,
        inputId: pending.input.inputId, operationRef: pending.input.operationRef })
    } else {this.feed.finishWith({ kind: 'diagnostic', code, sessionRef: this.sessionRef })}
    for (const item of this.queued.splice(0)) {item.done.resolve(failure(code, true))}
    this.interactions.clear(); this.wake()
  }
  private isOpen(): boolean { return this.state === 'open' }
  private hasControl(): boolean { return this.control !== undefined }
  private wake(): void { this.wakeup.resolve(); this.wakeup = deferred<void>() }
}

import { OpenCodeDriverSession } from './driver-session.ts'
import { createV2DriverBackend } from './v2-driver-backend.ts'
import { driverCompatibility } from './v2-driver-config.ts'
import type { OpenCodeV2DriverConfig } from './v2-driver-config.ts'

export function createV2DriverSession(config: OpenCodeV2DriverConfig) {
  // TypeScript's boolean contract does not constrain an injected Host callback
  // at runtime. A truthy object/number is neither a valid owner admission nor
  // physical process-stop attestation; do not let the shared Session SPI's
  // truthiness checks elevate those values to success.
  const qualified: OpenCodeV2DriverConfig = {
    ...config,
    probe: async signal => (await config.probe(signal)) === true,
    confirmStopped: async () => (await config.confirmStopped()) === true,
  }
  return new OpenCodeDriverSession({ ...qualified, ...(qualified.attachments ? { attachmentModel: qualified.attachments.model } : {}),
    engine: 'opencode-v2', compatibility: driverCompatibility(config) },
    signal => createV2DriverBackend(qualified, signal))
}
